internal static class Program {
  private static void Check(bool condition, string reason) {
    if (!condition)
      throw new InvalidOperationException(reason);
  }

  private static async Task Main() {

{
  int[] values = { 2, 4, 6 };
  int sum = 0;
  foreach (int value in values)
    sum += value;
  Check(sum == 12, "sum of all values");
  Check(Array.Empty<int>().Sum() == 0, "empty sum identity");
}

{
  int[] values = { 3, 8, 8 };
  int found = -1;
  for (int i = 0; i < values.Length; i++) {
    if (values[i] == 8) {
      found = i;
      break;
    }
  }
  Check(found == 1, "first matching position");
  Check(!Array.Exists(values, value => value == 9), "absent target");
}

{
  // Task 2: Guided modification
  int[] values = { 2, -3, 4, -1, 6 };
  int sum = 0;
  foreach (int value in values) {
    if (value < 0)
      continue;
    sum += value;
  }
  Check(sum == 12, "negatives skipped");
  Check(sum == values.Where(v => v >= 0).Sum(), "same as filtered sum");
}

{
  // Task 3: Independent construction
  bool TryFirstIndex(int[] items, int target, out int index) {
    for (int i = 0; i < items.Length; i++) {
      if (items[i] == target) {
        index = i;
        return true;
      }
    }
    index = -1;
    return false;
  }

  var values = new[] { 5, 7, 7 };
  Check(TryFirstIndex(values, 7, out int at) && at == 1, "first match");
  Check(!TryFirstIndex(values, 9, out _), "not found");
  Check(!TryFirstIndex(Array.Empty<int>(), 1, out _), "empty input");
}

{
  // Task 5: Boundary evidence
  int FirstIndex(int[] items, int target) {
    for (int i = 0; i < items.Length; i++) {
      if (items[i] == target)
        return i;
    }
    return -1;
  }
  int[] empty = Array.Empty<int>();
  int[] single = { 4 };
  int[] other = { 1, 2 };
  int[] repeated = { 4, 9, 4 };
  Check(FirstIndex(empty, 4) == -1, "empty input");
  Check(FirstIndex(single, 4) == 0, "singleton match");
  Check(FirstIndex(other, 4) == -1, "no match");
  Check(FirstIndex(repeated, 4) == 0, "repeated match returns the first");
}

{
  var values = new List<int> { 1, 2 };
  var query = values.Where(value => value > 1);
  values.Add(3);
  Check(query.SequenceEqual(new[] { 2, 3 }),
        "query sees later source state");
}

{
  var values = new List<int> { 1, 2 };
  int[] snapshot = values.Where(value => value > 1).ToArray();
  values.Add(3);
  Check(snapshot.SequenceEqual(new[] { 2 }), "snapshot remains stable");
  Check(values.Select(value => value * 10).ToArray().Length == 3,
        "projection count");
}

{
  // Task 3: Independent construction
  var stock = new Dictionary<string, int> { ["pear"] = 2, ["fig"] = 0 };
  stock["apple"] = 5;
  var kept = stock.Where(row => row.Value > 0);
  var ordered = kept.OrderBy(row => row.Key, StringComparer.Ordinal);
  var report = ordered.Select(row => $"{row.Key}={row.Value}");
  Check(report.SequenceEqual(new[] { "apple=5", "pear=2" }), "report");
}

{
  int count = 0;
  await Task.WhenAll(Enumerable.Range(0, 4).Select(
      _ => Task.Run(() => {
        for (int i = 0; i < 100; i++)
          Interlocked.Increment(ref count);
      })));
  Check(count == 400, "atomic count");
}

{
  var counts = new ConcurrentDictionary<string, int>();
  await Task.WhenAll(Enumerable.Range(0, 20).Select(
      _ => Task.Run(() => counts.AddOrUpdate(
                        "a", 1, (_, previous) => previous + 1))));
  Check(counts["a"] == 20, "concurrent key updates");
}

{
  // Task 3: Independent construction
  var counts = new ConcurrentDictionary<string, int>();
  string[] words = { "a", "b", "a", "a" };
  int Next(string key, int before) => before + 1;
  Task Add(string w) => Task.Run(() => counts.AddOrUpdate(w, 1, Next));
  await Task.WhenAll(words.Select(Add));
  Check(counts["a"] == 3 && counts["b"] == 1, "concurrent frequencies");
}
